1	/****************************************************************************
2	 * Contest 2026 team 008 - INA226 power monitor driver
3	 *
4	 * Two INA226 shunt monitors behind the TCA9548A (see cs_i2c_sw.h):
5	 *   CH4 -> total power input current   (address 0x40)
6	 *   CH5 -> soldering iron heater power (address 0x46)
7	 *
8	 * This is a register level driver, not a character device: the application
9	 * polls both monitors from its own timer and pushes the results to the UI.
10	 *
11	 * Register map (datasheet section 7.6):
12	 *   0x00 Configuration   0x01 Shunt Voltage   0x02 Bus Voltage
13	 *   0x03 Power           0x04 Current         0x05 Calibration
14	 *   0xFE Manufacturer ID (0x5449 = 'TI')
15	 ****************************************************************************/
16	
17	#include <nuttx/config.h>
18	
19	#include <stdint.h>
20	#include <stdbool.h>
21	#include <errno.h>
22	#include <syslog.h>
23	
24	#include <nuttx/arch.h>
25	
26	#include "cs_i2c_sw.h"
27	#include "ina226.h"
28	
29	/****************************************************************************
30	 * Pre-processor Definitions
31	 ****************************************************************************/
32	
33	/* Shunt resistor values in micro-ohms.  THESE MUST MATCH THE HARDWARE: an
34	 * error here scales both the current and the power reading by the same
35	 * factor.  The driver prints the resulting current LSB at start-up so it
36	 * can be checked against a bench meter.
37	 */
38	
39	#define CS_INA226_TOTAL_SHUNT_UOHM   2500u  /* 2.5 mOhm */
40	#define CS_INA226_IRON_SHUNT_UOHM    5000u  /* 5.0 mOhm */
41	
42	/* Target current resolution in micro-amps.  The datasheet suggests picking
43	 * a round value near Max_Expected_Current / 32768 so the current and power
44	 * registers come out in convenient units.  Both resistors below divide the
45	 * calibration formula exactly, so the effective resolution equals the
46	 * requested one with no truncation error.
47	 */
48	
49	#define CS_INA226_TOTAL_LSB_UA       1000u  /* 1 mA   -> +/-32.77 A */
50	#define CS_INA226_IRON_LSB_UA         500u  /* 0.5 mA -> +/-16.38 A */
51	
52	/* Slave addresses, set by the A1/A0 pins (datasheet table 2). */
53	
54	#define CS_INA226_ADDR_TOTAL         0x40   /* A1 = GND, A0 = GND */
55	#define CS_INA226_ADDR_IRON          0x46   /* A1 = VS,  A0 = VS  */
56	
57	#define CS_INA226_REG_CONFIG         0x00
58	#define CS_INA226_REG_SHUNT          0x01
59	#define CS_INA226_REG_BUS            0x02
60	#define CS_INA226_REG_POWER          0x03
61	#define CS_INA226_REG_CURRENT        0x04
62	#define CS_INA226_REG_CALIBRATION    0x05
63	#define CS_INA226_REG_MANUFACTURER   0xfe
64	
65	#define CS_INA226_MANUFACTURER_ID    0x5449   /* 'TI' */
66	
67	/* Configuration register: AVG = 16 samples, 1.1 ms bus + 1.1 ms shunt
68	 * conversions, continuous shunt and bus mode (datasheet table 5).
69	 * One full cycle takes 16 x (1.1 + 1.1) ms = 35.2 ms. */
70	
71	#define CS_INA226_CFG_AVG_16         (2u << 9)
72	#define CS_INA226_CFG_VBUSCT_1P1MS   (4u << 6)
73	#define CS_INA226_CFG_VSHCT_1P1MS    (4u << 3)
74	#define CS_INA226_CFG_MODE_CONT      (7u << 0)
75	#define CS_INA226_CFG_DEFAULT        (CS_INA226_CFG_AVG_16 | \
76	                                      CS_INA226_CFG_VBUSCT_1P1MS | \
77	                                      CS_INA226_CFG_VSHCT_1P1MS | \
78	                                      CS_INA226_CFG_MODE_CONT)
79	
80	#define CS_INA226_CONFIG_RESET       (1u << 15)
81	
82	/* Mark a device absent after this many consecutive failed reads. */
83	
84	#define CS_INA226_MAX_ERRORS         3
85	
86	/****************************************************************************
87	 * Private Types
88	 ****************************************************************************/
89	
90	struct cs_ina226_dev_s
91	{
92	  uint8_t  channel;      /* TCA9548A downstream channel */
93	  uint8_t  addr;         /* I2C slave address */
94	  uint16_t lsb_ua;       /* Requested current LSB, uA */
95	  uint32_t shunt_uohm;   /* Shunt resistor in micro-ohms */
96	  uint16_t cal;          /* Value written to the calibration register */
97	  uint32_t lsb_na;       /* Effective current LSB in nA */
98	  uint8_t  errors;       /* Consecutive read failures */
99	  bool     present;      /* Device answered the last access */
100	};
101	
102	/****************************************************************************
103	 * Private Data
104	 ****************************************************************************/
105	
106	static struct cs_ina226_dev_s g_ina226[CS_INA226_COUNT] =
107	{
108	  {
109	    CS_TCA_CH_INA_TOTAL, CS_INA226_ADDR_TOTAL, CS_INA226_TOTAL_LSB_UA,
110	    CS_INA226_TOTAL_SHUNT_UOHM, 0, 0, 0, false
111	  },
112	  {
113	    CS_TCA_CH_INA_IRON,  CS_INA226_ADDR_IRON,  CS_INA226_IRON_LSB_UA,
114	    CS_INA226_IRON_SHUNT_UOHM,  0, 0, 0, false
115	  }
116	};
117	
118	/****************************************************************************
119	 * Private Functions
120	 ****************************************************************************/
121	
122	/****************************************************************************
123	 * Name: cs_ina226_read_reg
124	 *
125	 * Read a 16-bit register using the repeated start shown in the datasheet
126	 * timing diagram (figure 23).
127	 ****************************************************************************/
128	
129	static int cs_ina226_read_reg(FAR struct cs_ina226_dev_s *dev, uint8_t reg,
130	                              FAR uint16_t *value)
131	{
132	  struct i2c_msg_s msg[2];
133	  uint8_t regaddr = reg;
134	  uint8_t buf[2];
135	  int ret;
136	
137	  msg[0].frequency = CS_I2C_FREQ;
138	  msg[0].addr      = dev->addr;
139	  msg[0].flags     = I2C_M_NOSTOP;   /* Keep the bus for the read */
140	  msg[0].buffer    = &regaddr;
141	  msg[0].length    = 1;
142	
143	  msg[1].frequency = CS_I2C_FREQ;
144	  msg[1].addr      = dev->addr;
145	  msg[1].flags     = I2C_M_READ;
146	  msg[1].buffer    = buf;
147	  msg[1].length    = 2;
148	
149	  ret = cs_i2c_transfer(dev->channel, msg, 2);
150	  if (ret < 0)
151	    {
152	      return ret;
153	    }
154	
155	  *value = (uint16_t)(((uint16_t)buf[0] << 8) | (uint16_t)buf[1]);
156	  return OK;
157	}
158	
159	/****************************************************************************
160	 * Name: cs_ina226_write_reg
161	 ****************************************************************************/
162	
163	static int cs_ina226_write_reg(FAR struct cs_ina226_dev_s *dev, uint8_t reg,
164	                               uint16_t value)
165	{
166	  struct i2c_msg_s msg;
167	  uint8_t tx[3];
168	
169	  tx[0] = reg;
170	  tx[1] = (uint8_t)(value >> 8);
171	  tx[2] = (uint8_t)(value & 0xff);
172	
173	  msg.frequency = CS_I2C_FREQ;
174	  msg.addr      = dev->addr;
175	  msg.flags     = 0;
176	  msg.buffer    = tx;
177	  msg.length    = sizeof(tx);
178	
179	  return cs_i2c_transfer(dev->channel, &msg, 1);
180	}
181	
182	/****************************************************************************
183	 * Name: cs_ina226_calibrate
184	 *
185	 * Program the calibration register from the shunt value.
186	 *
187	 *   CAL = 0.00512 / (Current_LSB[A] * R_shunt[ohm])
188	 *       = 5.12e9   / (Current_LSB[uA] * R_shunt[uohm])
189	 *
190	 * The result is truncated to an integer register, so the current LSB is
191	 * recomputed from the value actually written.  Skipping that step leaves a
192	 * fixed gain error of up to one part in 65535 on every current reading.
193	 *
194	 * Returned Value:
195	 *   OK, or -ERANGE when the shunt does not yield a usable calibration value.
196	 ****************************************************************************/
197	
198	static int cs_ina226_calibrate(FAR struct cs_ina226_dev_s *dev)
199	{
200	  uint64_t cal;
201	
202	  cal = 5120000000ull / ((uint64_t)dev->lsb_ua *
203	                         (uint64_t)dev->shunt_uohm);
204	  if (cal < 1 || cal > 65535)
205	    {
206	      syslog(LOG_ERR, "INA226 ch%u: %lu uOhm shunt cannot be calibrated "
207	             "with a %u uA LSB (cal=%llu)\n", dev->channel,
208	             (unsigned long)dev->shunt_uohm, (unsigned)dev->lsb_ua,
209	             (unsigned long long)cal);
210	      return -ERANGE;
211	    }
212	
213	  dev->cal    = (uint16_t)cal;
214	  dev->lsb_na = (uint32_t)(5120000000000ull / (cal * dev->shunt_uohm));
215	  return OK;
216	}
217	
218	/****************************************************************************
219	 * Name: cs_ina226_probe
220	 *
221	 * Identify the device and bring it into continuous conversion mode.
222	 ****************************************************************************/
223	
224	static int cs_ina226_probe(FAR struct cs_ina226_dev_s *dev)
225	{
226	  uint16_t id;
227	  int ret;
228	
229	  ret = cs_ina226_read_reg(dev, CS_INA226_REG_MANUFACTURER, &id);
230	  if (ret < 0)
231	    {
232	      return ret;
233	    }
234	
235	  if (id != CS_INA226_MANUFACTURER_ID)
236	    {
237	      syslog(LOG_WARNING, "INA226 ch%u addr 0x%02x: bad manufacturer ID "
238	             "0x%04x (expected 0x%04x)\n", dev->channel, dev->addr, id,
239	             CS_INA226_MANUFACTURER_ID);
240	      return -ENODEV;
241	    }
242	
243	  if (cs_ina226_calibrate(dev) < 0)
244	    {
245	      return -ERANGE;
246	    }
247	
248	  /* Reset, then configure for continuous conversion. */
249	
250	  ret = cs_ina226_write_reg(dev, CS_INA226_REG_CONFIG, CS_INA226_CONFIG_RESET);
251	  if (ret < 0)
252	    {
253	      return ret;
254	    }
255	
256	  up_udelay(1000);
257	
258	  ret = cs_ina226_write_reg(dev, CS_INA226_REG_CONFIG, CS_INA226_CFG_DEFAULT);
259	  if (ret < 0)
260	    {
261	      return ret;
262	    }
263	
264	  ret = cs_ina226_write_reg(dev, CS_INA226_REG_CALIBRATION, dev->cal);
265	  if (ret < 0)
266	    {
267	      return ret;
268	    }
269	
270	  syslog(LOG_INFO, "INA226 ch%u addr 0x%02x: %lu uOhm shunt, cal=%u "
271	         "(%lu nA/count, +/-%.2f A full scale)\n",
272	         dev->channel, dev->addr, (unsigned long)dev->shunt_uohm, dev->cal,
273	         (unsigned long)dev->lsb_na,
274	         32767.0 * (double)dev->lsb_na / 1.0e9);
275	  return OK;
276	}
277	
278	/****************************************************************************
279	 * Public Functions
280	 ****************************************************************************/
281	
282	int cs_ina226_init(void)
283	{
284	  unsigned int i;
285	
286	  if (!cs_i2c_bus_ready())
287	    {
288	      int ret = cs_i2c_bus_init();
289	      if (ret < 0)
290	        {
291	          return ret;
292	        }
293	    }
294	
295	  for (i = 0; i < CS_INA226_COUNT; i++)
296	    {
297	      if (cs_ina226_probe(&g_ina226[i]) < 0)
298	        {
299	          /* Report once, then stay quiet until cs_ina226_retry() finds it. */
300	
301	          syslog(LOG_WARNING, "INA226: monitor %u not detected on TCA ch%u "
302	                 "(addr 0x%02x)\n", i, g_ina226[i].channel,
303	                 g_ina226[i].addr);
304	          g_ina226[i].present = false;
305	        }
306	      else
307	        {
308	          g_ina226[i].present = true;
309	          g_ina226[i].errors  = 0;
310	        }
311	    }
312	
313	  return OK;
314	}
315	
316	bool cs_ina226_present(uint8_t dev)
317	{
318	  if (dev >= CS_INA226_COUNT)
319	    {
320	      return false;
321	    }
322	
323	  return g_ina226[dev].present;
324	}
325	
326	int cs_ina226_read(uint8_t dev, FAR struct ina226_sample_s *out)
327	{
328	  FAR struct cs_ina226_dev_s *d;
329	  uint16_t raw;
330	  int ret;
331	
332	  if (dev >= CS_INA226_COUNT || out == NULL)
333	    {
334	      return -EINVAL;
335	    }
336	
337	  d = &g_ina226[dev];
338	  if (!d->present)
339	    {
340	      /* Do not burn four ACK timeouts per poll on a monitor that is not
341	       * plugged in. */
342	
343	      return -ENODEV;
344	    }
345	
346	  ret = cs_ina226_read_reg(d, CS_INA226_REG_BUS, &raw);
347	  if (ret < 0)
348	    {
349	      goto lost;
350	    }
351	
352	  /* Bus voltage is unsigned; bit 15 is always zero. */
353	
354	  out->bus_mv = (uint32_t)(raw & 0x7fff) * 5u / 4u;
355	
356	  ret = cs_ina226_read_reg(d, CS_INA226_REG_SHUNT, &raw);
357	  if (ret < 0)
358	    {
359	      goto lost;
360	    }
361	
362	  out->shunt_uv = (int32_t)(int16_t)raw * 5 / 2;
363	
364	  ret = cs_ina226_read_reg(d, CS_INA226_REG_CURRENT, &raw);
365	  if (ret < 0)
366	    {
367	      goto lost;
368	    }
369	
370	  out->current_ma = (int32_t)(((int64_t)(int16_t)raw * d->lsb_na) / 1000000);
371	
372	  ret = cs_ina226_read_reg(d, CS_INA226_REG_POWER, &raw);
373	  if (ret < 0)
374	    {
375	      goto lost;
376	    }
377	
378	  /* The power LSB is internally fixed at 25 x Current_LSB. */
379	
380	  out->power_mw = (uint32_t)(((uint64_t)raw * 25ull * d->lsb_na) /
381	                             1000000ull);
382	
383	  d->errors = 0;
384	  return OK;
385	
386	lost:
387	  if (++d->errors >= CS_INA226_MAX_ERRORS)
388	    {
389	      d->errors  = 0;
390	      d->present = false;
391	      syslog(LOG_WARNING, "INA226: monitor %u lost on TCA ch%u\n", dev,
392	             d->channel);
393	    }
394	
395	  return ret;
396	}
397	
398	void cs_ina226_retry(void)
399	{
400	  unsigned int i;
401	
402	  if (!cs_i2c_bus_ready())
403	    {
404	      return;
405	    }
406	
407	  for (i = 0; i < CS_INA226_COUNT; i++)
408	    {
409	      FAR struct cs_ina226_dev_s *d = &g_ina226[i];
410	
411	      if (d->present)
412	        {
413	          continue;
414	        }
415	
416	      if (cs_ina226_probe(d) == OK)
417	        {
418	          d->present = true;
419	          d->errors  = 0;
420	          syslog(LOG_INFO, "INA226: monitor %u reappeared on TCA ch%u\n", i,
421	                 d->channel);
422	        }
423	    }
424	}
