1	/****************************************************************************
2	 * Contest 2026 team 008 - charging station main
3	 *
4	 * Entry point: initializes LVGL, display and touchscreen, then
5	 * enters the LVGL event loop with the charging station UI.
6	 * Reads the SW3538 chargers and INA226 monitors over the software I2C
7	 * bus (D4/D5) every ~500ms.
8	 ****************************************************************************/
9	
10	#include <nuttx/config.h>
11	
12	#include <stdio.h>
13	#include <stdlib.h>
14	#include <string.h>
15	#include <syslog.h>
16	#include <unistd.h>
17	
18	#include <lvgl/lvgl.h>
19	
20	#include "charging_station_ui.h"
21	#include "cs_i2c_sw.h"
22	#include "sw3538.h"
23	#include "ina226.h"
24	#include "iron.h"
25	
26	/****************************************************************************
27	 * Pre-processor Definitions
28	 ****************************************************************************/
29	
30	#define INA226_RETRY_TICKS  50   /* 50 x 100ms = 5s between re-probes */
31	
32	/****************************************************************************
33	 * Private Data
34	 ****************************************************************************/
35	
36	static bool g_sw3538_ok[4];
37	
38	/* Channel read by the next tick; the four SW3538 modules are polled in
39	 * rotation so no single tick carries the whole bus sweep. */
40	
41	static int  g_poll_chan;
42	
43	/****************************************************************************
44	 * Private Functions
45	 ****************************************************************************/
46	
47	/****************************************************************************
48	 * Name: sw3538_poll_channel
49	 *
50	 * Read one SW3538 and push its data into the matching UI channel card.
51	 * On failure, mark the channel idle but keep the app running.
52	 *
53	 * One channel takes about 23ms (four ADC conversions, each waiting 5ms for
54	 * the chip to latch a result), so the four channels are spread across four
55	 * consecutive ticks rather than read back to back.  A full sweep still
56	 * completes every 400ms, but no single tick blocks the LVGL loop and the
57	 * touch input timer for ~92ms.
58	 ****************************************************************************/
59	
60	static void sw3538_poll_channel(int channel)
61	{
62	  struct sw3538_status_s st;
63	  int ret;
64	
65	  if (!g_sw3538_ok[channel])
66	    {
67	      return;
68	    }
69	
70	  ret = sw3538_read_status_channel(channel, &st);
71	  if (ret < 0)
72	    {
73	      syslog(LOG_WARNING, "SW3538 CH%d read failed: %d\n", channel + 1, ret);
74	      cs_ui_set_channel_online(channel, false, false);
75	      return;
76	    }
77	
78	  cs_ui_set_channel_ports(channel, (float)st.vout_mv / 1000.0f,
79	                          (float)st.ic_ma / 1000.0f,
80	                          (float)st.vout_mv / 1000.0f,
81	                          (float)st.ia_ma / 1000.0f,
82	                          sw3538_proto_name(st.proto), st.temp_c,
83	                          st.temp_valid);
84	  cs_ui_set_channel_online(channel, (st.online & 0x02) != 0,
85	                           (st.online & 0x01) != 0);
86	
87	  syslog(LOG_INFO, "SW3538 CH%d: Vout=%dmV Ic=%dmA Ia=%dmA "
88	         "temp=%s%dC proto=%d(%s)\n", channel + 1, st.vout_mv,
89	         st.ic_ma, st.ia_ma, st.temp_valid ? "" : "N/A ", st.temp_c,
90	         st.proto, sw3538_proto_name(st.proto));
91	}
92	
93	/****************************************************************************
94	 * Name: ina226_poll
95	 *
96	 * Read the total input monitor and the soldering iron monitor.
97	 *
98	 * The iron heater is switched by a 1 Hz software PWM, so a single 35ms
99	 * conversion window lands either fully on or fully off; the value is a
100	 * snapshot rather than an average, and a single low sample is not a fault.
101	 ****************************************************************************/
102	
103	static void ina226_poll(void)
104	{
105	  struct ina226_sample_s s;
106	
107	  if (cs_ina226_read(CS_INA226_TOTAL, &s) == OK)
108	    {
109	      cs_ui_set_input_power((float)s.bus_mv / 1000.0f,
110	                            (float)s.current_ma / 1000.0f,
111	                            (float)s.power_mw / 1000.0f, true);
112	
113	      syslog(LOG_INFO, "INA226 IN : %lumV %ldmA %lumW\n",
114	             (unsigned long)s.bus_mv, (long)s.current_ma,
115	             (unsigned long)s.power_mw);
116	    }
117	  else
118	    {
119	      cs_ui_set_input_power(0.0f, 0.0f, 0.0f, false);
120	    }
121	
122	  if (cs_ina226_read(CS_INA226_IRON, &s) == OK)
123	    {
124	      cs_ui_set_iron_power((float)s.bus_mv / 1000.0f,
125	                           (float)s.current_ma / 1000.0f,
126	                           (float)s.power_mw / 1000.0f, true);
127	
128	      syslog(LOG_INFO, "INA226 IRON: %lumV %ldmA %lumW\n",
129	             (unsigned long)s.bus_mv, (long)s.current_ma,
130	             (unsigned long)s.power_mw);
131	    }
132	  else
133	    {
134	      cs_ui_set_iron_power(0.0f, 0.0f, 0.0f, false);
135	    }
136	}
137	
138	/****************************************************************************
139	 * Name: data_timer_cb
140	 *
141	 * Periodically refresh simulated data + real SW3538 readings.
142	 ****************************************************************************/
143	
144	static void data_timer_cb(lv_timer_t *timer)
145	{
146	  static int slow = 0;
147	  static int retry = 0;
148	  struct iron_status_s ist;
149	
150	  cs_ui_data_tick();
151	
152	  /* Sync UI intent (target temp / heater on / PID) into the iron module */
153	  float kp;
154	  float ki;
155	  float kd;
156	
157	  iron_set_target(cs_ui_get_iron_target());
158	  iron_set_heater(cs_ui_get_iron_on());
159	  iron_set_standby_temp(cs_ui_get_standby_temp());
160	  cs_ui_get_iron_pid(&kp, &ki, &kd);
161	  iron_set_pid(kp * 0.2f, ki * 0.4f, kd * 0.2f);
162	
163	  /* Soldering iron: PID tick every 100ms */
164	  iron_tick();
165	  iron_get_status(&ist);
166	  cs_ui_set_iron_real(ist.temp_c, ist.power_pct, ist.heating, ist.sensor_ok);
167	  cs_ui_set_iron_sleep(ist.sleep_active,
168	                       (ist.sleep_active ? ist.target_eff_c : ist.target_c));
169	
170	  /* SW3538 sweep: one channel per 100ms tick, so the bus work never blocks
171	   * the LVGL loop for longer than a single channel (~23ms). */
172	  sw3538_poll_channel(g_poll_chan);
173	  if (++g_poll_chan >= 4)
174	    {
175	      g_poll_chan = 0;
176	    }
177	
178	  /* INA226 is cheap (about 2ms for both monitors). */
179	  if (++slow >= 5)
180	    {
181	      slow = 0;
182	      ina226_poll();
183	    }
184	
185	  /* Re-probe monitors that were absent at boot. */
186	  if (++retry >= INA226_RETRY_TICKS)
187	    {
188	      retry = 0;
189	      cs_ina226_retry();
190	    }
191	
192	  (void)timer;
193	}
194	
195	/****************************************************************************
196	 * Name: lv_nuttx_loop
197	 *
198	 * Standard LVGL poll loop.
199	 ****************************************************************************/
200	
201	static void lv_nuttx_loop(void)
202	{
203	  while (1)
204	    {
205	      uint32_t idle;
206	
207	      idle = lv_timer_handler();
208	      idle = idle ? idle : 1;
209	      usleep(idle * 1000);
210	    }
211	}
212	
213	/****************************************************************************
214	 * Public Functions
215	 ****************************************************************************/
216	
217	int main(int argc, FAR char *argv[])
218	{
219	  lv_nuttx_dsc_t info;
220	  lv_nuttx_result_t result;
221	
222	  syslog(LOG_INFO, "Charging Station starting\n");
223	
224	  /* Init soldering iron GPIO + MAX6675 probe (non-fatal) */
225	  iron_init();
226	
227	  /* Bring up the software I2C bus and probe the TCA9548A plus the four
228	   * SW3538 modules.  Every step is non-fatal: the UI must still come up
229	   * with no hardware attached. */
230	  if (sw3538_init() < 0)
231	    {
232	      syslog(LOG_WARNING, "Charging Station: TCA9548A not detected\n");
233	    }
234	  else
235	    {
236	      int channel;
237	
238	      for (channel = 0; channel < 4; channel++)
239	        {
240	          struct sw3538_status_s st;
241	
242	          if (sw3538_read_status_channel(channel, &st) == OK)
243	            {
244	              g_sw3538_ok[channel] = true;
245	              syslog(LOG_INFO, "Charging Station: SW3538 CH%d ready\n",
246	                     channel + 1);
247	            }
248	          else
249	            {
250	              syslog(LOG_WARNING, "Charging Station: SW3538 CH%d absent\n",
251	                     channel + 1);
252	            }
253	        }
254	    }
255	
256	  /* Probe the two INA226 power monitors on TCA channels 4 and 5. */
257	
258	  if (cs_ina226_init() < 0)
259	    {
260	      syslog(LOG_WARNING, "Charging Station: INA226 init failed\n");
261	    }
262	
263	  lv_init();
264	
265	  lv_nuttx_dsc_init(&info);
266	
267	#ifdef CONFIG_LV_USE_NUTTX_LCD
268	  info.fb_path = "/dev/lcd0";
269	#endif
270	
271	  lv_nuttx_init(&info, &result);
272	
273	  if (result.disp == NULL)
274	    {
275	      syslog(LOG_ERR, "Charging Station: display init failed\n");
276	      lv_deinit();
277	      return -1;
278	    }
279	
280	  /* Build the charging station UI */
281	  if (cs_ui_init(lv_screen_active()) < 0)
282	    {
283	      syslog(LOG_ERR, "Charging Station: UI init failed\n");
284	      lv_nuttx_deinit(&result);
285	      lv_deinit();
286	      return -1;
287	    }
288	
289	  /* Start data simulation timer (100ms) */
290	  lv_timer_create(data_timer_cb, 100, NULL);
291	
292	  syslog(LOG_INFO, "Charging Station: display res=%ldx%ld\n",
293	         (long)lv_display_get_horizontal_resolution(result.disp),
294	         (long)lv_display_get_vertical_resolution(result.disp));
295	
296	  if (result.indev)
297	    {
298	      /* Speed up touch reading: 20ms poll period (faster response) */
299	      lv_indev_set_mode(result.indev, LV_INDEV_MODE_TIMER);
300	      lv_timer_t *t = lv_indev_get_read_timer(result.indev);
301	      if (t)
302	        {
303	          lv_timer_set_period(t, 20);
304	        }
305	      syslog(LOG_INFO, "Charging Station: touchscreen registered (20ms poll)\n");
306	    }
307	  else
308	    {
309	      syslog(LOG_WARNING, "Charging Station: no touchscreen (indev NULL)\n");
310	    }
311	
312	  /* Enter the LVGL event loop */
313	  syslog(LOG_INFO, "Charging Station: entering poll loop\n");
314	  lv_nuttx_loop();
315	
316	  lv_nuttx_deinit(&result);
317	  lv_deinit();
318	  return 0;
319	}
