1	/****************************************************************************
2	 * Contest 2026 team 008 - soldering iron module
3	 *
4	 * MAX6675 K-thermocouple reader over software SPI (bit-bang GPIO),
5	 * software PWM heater control and a simple PID loop.
6	 *
7	 * Wiring (Arduino headers):
8	 *   MAX6675 SCK -> D8  (PE3)
9	 *   MAX6675 CS  -> D7  (PI8)
10	 *   MAX6675 SO  -> D6  (PE6)
11	 *   Heater PWM  -> D3  (PA6) -> NPN transistor -> MOSFET -> 24V iron
12	 *   Sleep sense -> D2  (PG3)
13	 *
14	 * The remaining Arduino pins are owned by other modules:
15	 *   D4 (PK1) / D5 (PA8) -> TCA9548A software I2C, see cs_i2c_sw.c
16	 *   D9 (PH15)           -> board ID input, not used yet
17	 *
18	 * MAX6675 protocol (16-bit read):
19	 *   D15=0(dummy), D14-D3=temp(12bit, 0.25C/bit),
20	 *   D2=1 thermocouple open, D1=0, D0=tri-state
21	 ****************************************************************************/
22	
23	#include <nuttx/config.h>
24	
25	#include <stdio.h>
26	#include <stdint.h>
27	#include <stdbool.h>
28	#include <unistd.h>
29	#include <math.h>
30	#include <syslog.h>
31	
32	#include <nuttx/arch.h>
33	#include <arch/board/board.h>
34	
35	#include "iron.h"
36	
37	/* GPIO config macros come from chip headers not on the app include
38	 * path; use explicit values via the generic stm32 API forward decls.
39	 */
40	extern int  stm32_configgpio(uint32_t cfgset);
41	extern void stm32_gpiowrite(uint32_t pinset, bool value);
42	extern bool stm32_gpioread(uint32_t pinset);
43	
44	/****************************************************************************
45	 * Pre-processor Definitions
46	 ****************************************************************************/
47	
48	/* --- GPIO pin assignments (Arduino D2/D3/D6/D7/D8) ---
49	 * stm32_gpio.h is not on the app include path, so pinsets are built
50	 * from the documented bit layout:
51	 *   MODE bits18-19 (OUTPUT=1<<18), SPEED bits10-11 (50MHz=2<<10),
52	 *   OUTPUT_SET bit8 (0x100), PORT bits4-7 (A=0,E=4,I=8), PIN bits0-3
53	 */
54	#define GPIO_OUTPUT_VAL     (1u << 18)
55	#define GPIO_SPEED_50MHZ    (2u << 10)
56	#define GPIO_OUTPUT_SETBIT  (1u << 8)
57	#define GPIO_PULLUP         (1u << 16)
58	
59	#define IRON_GPIO_SCK    (GPIO_OUTPUT_VAL | GPIO_SPEED_50MHZ | \
60	                          (4u << 4) | 3u)              /* D8 = PE3  */
61	#define IRON_GPIO_CS     (GPIO_OUTPUT_VAL | GPIO_SPEED_50MHZ | \
62	                          GPIO_OUTPUT_SETBIT | (8u << 4) | 8u)  /* D7 = PI8 */
63	#define IRON_GPIO_SO     ((4u << 4) | 6u)               /* D6 = PE6 input */
64	#define IRON_GPIO_HEAT   (GPIO_OUTPUT_VAL | GPIO_SPEED_50MHZ | \
65	                          (0u << 4) | 6u)              /* D3 = PA6  */
66	#define IRON_GPIO_SLEEP  (GPIO_PULLUP | (6u << 4) | 3u) /* D2 = PG3, active low */
67	
68	/* --- Timing (us) --- */
69	#define IRON_SPI_HALF_PERIOD_US  2    /* ~250kHz bit clock */
70	#define IRON_TICK_MS             100  /* PID period */
71	
72	/* --- PID limits --- */
73	#define IRON_TEMP_MIN     100
74	#define IRON_TEMP_MAX     480
75	#define IRON_TEMP_CUTOFF  500
76	#define IRON_PWR_MAX      100.0f
77	#define IRON_PID_DT       (IRON_TICK_MS / 1000.0f)
78	#define IRON_PID_KP_MAX   20.0f
79	#define IRON_PID_KI_MAX   2.0f
80	#define IRON_PID_KD_MAX   20.0f
81	#define IRON_SAMPLE_MAX_AGE  0.6f
82	
83	/* Software PWM: the iron module ticks every 100ms; the PWM cycle spans
84	 * IRON_PWM_TICKS ticks => 1s period (1Hz). Soldering irons have large
85	 * thermal inertia, so 1Hz duty control is fine. power% => the heater
86	 * stays ON for the first N slices of each cycle, OFF for the rest. */
87	#define IRON_PWM_TICKS       10   /* 1s cycle = 10 x 100ms slices */
88	
89	/* Derivative low-pass: limit D-term response per tick to avoid
90	 * oscillation from quantized (100ms-sampled) temperature. */
91	#define IRON_D_MAX_SLOPE     8.0f   /* max % output change from D per tick */
92	
93	/* JBC245 sleep detection (Arduino D2 = PG3, active low with pull-up) */
94	#define IRON_SLEEP_DEBOUNCE_TICKS 3   /* 300ms bounce filter */
95	#define IRON_SLEEP_ENTER_TICKS    30  /* 3s in stand before cooling */
96	#define IRON_STANDBY_DEFAULT_C    200
97	
98	/****************************************************************************
99	 * Private Data
100	 ****************************************************************************/
101	
102	static float g_temp_c      = 25.0f;
103	static int   g_target_c    = 350;
104	static bool  g_heating     = false;
105	static bool  g_sensor_ok   = false;
106	static float g_kp          = 3.0f;
107	static float g_ki          = 0.05f;
108	static float g_kd          = 1.5f;
109	static float g_power       = 0.0f;   /* 0..100 */
110	
111	/* PID state */
112	static float g_integral    = 0.0f;
113	static float g_last_temp_c = 25.0f;
114	static bool  g_have_sample = false;
115	static float g_sample_age  = 0.0f;
116	
117	/* Software PWM state: counts down every tick */
118	static int   g_pwm_slice   = 0;
119	
120	/* JBC245 sleep state */
121	static bool  g_sleep_pin_deb   = false;
122	static int   g_sleep_deb_cnt   = 0;
123	static int   g_sleep_ticks     = 0;
124	static int   g_sleep_stage     = IRON_SLEEP_ACTIVE;
125	static int   g_standby_c       = IRON_STANDBY_DEFAULT_C;
126	static int   g_target_eff_c    = 350;
127	
128	/****************************************************************************
129	 * Private Functions
130	 ****************************************************************************/
131	
132	/****************************************************************************
133	 * Name: iron_spi_delay
134	 ****************************************************************************/
135	
136	static inline void iron_spi_delay(void)
137	{
138	  up_udelay(IRON_SPI_HALF_PERIOD_US);
139	}
140	
141	/****************************************************************************
142	 * Name: max6675_read
143	 *
144	 * Bit-bang a 16-bit read from the MAX6675.
145	 * Returns 16-bit raw value (D2 = thermocouple open flag).
146	 ****************************************************************************/
147	
148	static uint16_t max6675_read(void)
149	{
150	  uint16_t value = 0;
151	  int i;
152	
153	  /* CS low to start */
154	  stm32_gpiowrite(IRON_GPIO_CS, false);
155	  iron_spi_delay();
156	
157	  /* Read 16 bits MSB first.  The MAX6675 updates SO after the falling
158	   * edge; sample each bit while SCK is low and stable. */
159	  for (i = 0; i < 16; i++)
160	    {
161	      /* SCK low -> data valid to read */
162	      stm32_gpiowrite(IRON_GPIO_SCK, false);
163	      iron_spi_delay();
164	
165	      /* Sample SO on rising edge per MAX6675: data changes on falling
166	       * edge, so read while clock is low (stable). */
167	      value = (value << 1);
168	      if (stm32_gpioread(IRON_GPIO_SO))
169	        {
170	          value |= 1;
171	        }
172	
173	      /* SCK high */
174	      stm32_gpiowrite(IRON_GPIO_SCK, true);
175	      iron_spi_delay();
176	    }
177	
178	  /* CS high to end */
179	  stm32_gpiowrite(IRON_GPIO_CS, true);
180	  iron_spi_delay();
181	
182	  return value;
183	}
184	
185	/****************************************************************************
186	 * Name: max6675_temp
187	 *
188	 * Decode 16-bit read into Celsius. Returns -1000 if thermocouple open.
189	 ****************************************************************************/
190	
191	static bool max6675_temp(uint16_t raw, FAR float *temp_c)
192	{
193	  uint16_t code;
194	
195	  if (temp_c == NULL || (raw & 0x8000) != 0 || (raw & 0x0002) != 0 ||
196	      (raw & 0x0004) != 0)
197	    {
198	      return false;
199	    }
200	
201	  code = (raw >> 3) & 0x0fff;
202	  *temp_c = (float)code * 0.25f;
203	  return *temp_c >= 0.0f && *temp_c <= 1023.75f;
204	}
205	
206	/****************************************************************************
207	 * Name: iron_pid_update
208	 *
209	 * Compute heater power % from PID on temperature error.
210	 ****************************************************************************/
211	
212	static void iron_pid_update(float dt)
213	{
214	  float error;
215	  float p_term;
216	  float i_term;
217	  float d_term;
218	  float d_slope;
219	  float candidate;
220	
221	  if (!g_heating || !g_sensor_ok || !g_have_sample)
222	    {
223	      g_power = 0.0f;
224	      g_integral = 0.0f;
225	      return;
226	    }
227	
228	  error = (float)g_target_eff_c - g_temp_c;
229	  p_term = g_kp * error;
230	  d_slope = (g_temp_c - g_last_temp_c) / dt;
231	  if (d_slope > IRON_D_MAX_SLOPE) d_slope = IRON_D_MAX_SLOPE;
232	  if (d_slope < -IRON_D_MAX_SLOPE) d_slope = -IRON_D_MAX_SLOPE;
233	  d_term = -g_kd * d_slope;
234	
235	  /* Conditional integration: do not integrate farther into saturation. */
236	  candidate = p_term + g_ki * g_integral + d_term;
237	  if (!((candidate >= IRON_PWR_MAX && error > 0.0f) ||
238	        (candidate <= 0.0f && error < 0.0f)))
239	    {
240	      g_integral += error * dt;
241	      if (g_integral > 1000.0f) g_integral = 1000.0f;
242	      if (g_integral < -1000.0f) g_integral = -1000.0f;
243	    }
244	
245	  i_term = g_ki * g_integral;
246	  g_power = p_term + i_term + d_term;
247	  if (g_power < 0.0f) g_power = 0.0f;
248	  if (g_power > IRON_PWR_MAX) g_power = IRON_PWR_MAX;
249	}
250	
251	/****************************************************************************
252	 * Name: iron_pwm_apply
253	 *
254	 * Software PWM: turn heater GPIO on/off based on power %.
255	 * Called once per tick (100ms). We split the 100ms into N slices and
256	 * keep the heater on for the first (power%) slices.
257	 ****************************************************************************/
258	
259	static void iron_pwm_apply(void)
260	{
261	  int on_slices = (int)(g_power / 100.0f * IRON_PWM_TICKS);
262	
263	  if (!g_heating || on_slices <= 0)
264	    {
265	      g_pwm_slice = 0;
266	      stm32_gpiowrite(IRON_GPIO_HEAT, false);
267	      return;
268	    }
269	
270	  if (on_slices >= IRON_PWM_TICKS)
271	    {
272	      stm32_gpiowrite(IRON_GPIO_HEAT, true);
273	      return;
274	    }
275	
276	  stm32_gpiowrite(IRON_GPIO_HEAT, g_pwm_slice < on_slices);
277	  g_pwm_slice++;
278	  if (g_pwm_slice >= IRON_PWM_TICKS)
279	    {
280	      g_pwm_slice = 0;
281	    }
282	}
283	
284	/****************************************************************************
285	 * Name: iron_sleep_tick
286	 *
287	 * Debounce the JBC245 SLEEP pin and drive the sleep stage:
288	 *   ACTIVE -> HOLD (in stand) -> STANDBY_TEMP after IRON_SLEEP_ENTER_TICKS.
289	 *   Leave stand at any time: back to ACTIVE and restore the user target.
290	 ****************************************************************************/
291	
292	static void iron_sleep_tick(void)
293	{
294	  bool raw;
295	  bool sleep_now;
296	
297	  raw = !stm32_gpioread(IRON_GPIO_SLEEP);   /* active low: in stand */
298	
299	  /* Bounce filter: require N consecutive identical samples. */
300	  if (raw != g_sleep_pin_deb)
301	    {
302	      g_sleep_deb_cnt++;
303	      if (g_sleep_deb_cnt >= IRON_SLEEP_DEBOUNCE_TICKS)
304	        {
305	          g_sleep_pin_deb = raw;
306	          g_sleep_deb_cnt = 0;
307	        }
308	    }
309	  else
310	    {
311	      g_sleep_deb_cnt = 0;
312	    }
313	
314	  sleep_now = g_sleep_pin_deb;
315	
316	  if (!sleep_now && g_sleep_stage != IRON_SLEEP_ACTIVE)
317	    {
318	      /* Picked up: restore user target and PID history. */
319	      g_sleep_stage = IRON_SLEEP_ACTIVE;
320	      g_sleep_ticks = 0;
321	      g_integral = 0.0f;
322	      g_last_temp_c = g_temp_c;
323	      g_target_eff_c = g_target_c;
324	    }
325	  else if (sleep_now && g_sleep_stage == IRON_SLEEP_ACTIVE)
326	    {
327	      g_sleep_stage = IRON_SLEEP_HOLD;
328	      g_sleep_ticks = 0;
329	    }
330	  else if (g_sleep_stage == IRON_SLEEP_HOLD)
331	    {
332	      g_sleep_ticks++;
333	      if (g_sleep_ticks >= IRON_SLEEP_ENTER_TICKS)
334	        {
335	          g_sleep_stage = IRON_SLEEP_STANDBY_TEMP;
336	          g_integral = 0.0f;
337	          g_target_eff_c = g_standby_c;
338	        }
339	    }
340	}
341	
342	
343	int iron_init(void)
344	{
345	  /* Configure GPIO pins */
346	  stm32_configgpio(IRON_GPIO_SCK);
347	  stm32_configgpio(IRON_GPIO_CS);
348	  stm32_configgpio(IRON_GPIO_SO);
349	  stm32_configgpio(IRON_GPIO_HEAT);
350	  stm32_configgpio(IRON_GPIO_SLEEP);
351	
352	  /* Idle states: CS high, clock low, heater off */
353	  stm32_gpiowrite(IRON_GPIO_CS, true);
354	  stm32_gpiowrite(IRON_GPIO_SCK, false);
355	  stm32_gpiowrite(IRON_GPIO_HEAT, false);
356	
357	  /* Probe MAX6675 */
358	  {
359	    uint16_t raw = max6675_read();
360	    float t;
361	
362	    if (!max6675_temp(raw, &t))
363	      {
364	        syslog(LOG_WARNING, "IRON: invalid MAX6675 frame (raw=0x%04x)\n", raw);
365	        g_sensor_ok = false;
366	      }
367	    else
368	      {
369	        g_temp_c = t;
370	        g_last_temp_c = t;
371	        g_have_sample = true;
372	        g_sample_age = 0.0f;
373	        g_sensor_ok = true;
374	        syslog(LOG_INFO, "IRON: MAX6675 ok, T=%.1fC (raw=0x%04x)\n", t, raw);
375	      }
376	  }
377	
378	  return 0;
379	}
380	
381	void iron_tick(void)
382	{
383	  static int read_div = 0;
384	  uint16_t raw;
385	  float t;
386	  bool fresh_sample = false;
387	
388	  g_sample_age += IRON_PID_DT;
389	
390	  /* JBC245 sleep detection runs every tick, before sampling. */
391	  iron_sleep_tick();
392	
393	  /* CS high starts a conversion.  Read only after three 100ms ticks so the
394	   * MAX6675 has exceeded its 220ms maximum conversion time. */
395	  if (++read_div >= 3)
396	    {
397	      read_div = 0;
398	      raw = max6675_read();
399	
400	      if (max6675_temp(raw, &t))
401	        {
402	          if (t >= IRON_TEMP_CUTOFF)
403	            {
404	              syslog(LOG_WARNING, "IRON: over-temperature %.1fC\n", t);
405	              g_sensor_ok = false;
406	            }
407	          else
408	            {
409	              g_last_temp_c = g_temp_c;
410	              g_temp_c = t;
411	              g_sample_age = 0.0f;
412	              g_have_sample = true;
413	              g_sensor_ok = true;
414	              fresh_sample = true;
415	            }
416	        }
417	      else
418	        {
419	          syslog(LOG_WARNING, "IRON: invalid MAX6675 frame (raw=0x%04x)\n", raw);
420	          g_sensor_ok = false;
421	        }
422	    }
423	
424	  if (!g_sensor_ok || g_sample_age > IRON_SAMPLE_MAX_AGE)
425	    {
426	      /* A stale or invalid sensor reading must always shut the heater off. */
427	      g_sensor_ok = false;
428	      g_power = 0.0f;
429	      g_integral = 0.0f;
430	      g_pwm_slice = 0;
431	      stm32_gpiowrite(IRON_GPIO_HEAT, false);
432	      return;
433	    }
434	
435	  if (fresh_sample)
436	    {
437	      iron_pid_update(IRON_PID_DT * 3.0f);
438	    }
439	
440	  iron_pwm_apply();
441	}
442	
443	void iron_set_target(int temp_c)
444	{
445	  if (temp_c < IRON_TEMP_MIN) temp_c = IRON_TEMP_MIN;
446	  if (temp_c > IRON_TEMP_MAX) temp_c = IRON_TEMP_MAX;
447	  if (temp_c != g_target_c)
448	    {
449	      g_integral = 0.0f;
450	      g_last_temp_c = g_temp_c;
451	    }
452	
453	  g_target_c = temp_c;
454	  if (g_sleep_stage == IRON_SLEEP_ACTIVE)
455	    {
456	      g_target_eff_c = temp_c;
457	    }
458	}
459	
460	void iron_set_heater(bool on)
461	{
462	  g_heating = on;
463	  if (!on)
464	    {
465	      g_integral = 0.0f;
466	      g_last_temp_c = g_temp_c;
467	      g_power = 0.0f;
468	      g_pwm_slice = 0;
469	      g_sleep_stage = IRON_SLEEP_ACTIVE;
470	      g_sleep_ticks = 0;
471	      g_sleep_pin_deb = !stm32_gpioread(IRON_GPIO_SLEEP);
472	      g_sleep_deb_cnt = 0;
473	      g_target_eff_c = g_target_c;
474	      stm32_gpiowrite(IRON_GPIO_HEAT, false);
475	    }
476	}
477	
478	void iron_set_pid(float p, float i, float d)
479	{
480	  if (!isfinite(p) || !isfinite(i) || !isfinite(d) || p < 0.0f ||
481	      i < 0.0f || d < 0.0f || p > IRON_PID_KP_MAX ||
482	      i > IRON_PID_KI_MAX || d > IRON_PID_KD_MAX)
483	    {
484	      syslog(LOG_WARNING, "IRON: rejected invalid PID P=%.2f I=%.2f D=%.2f\n", p, i, d);
485	      return;
486	    }
487	
488	  if (p != g_kp || i != g_ki || d != g_kd)
489	    {
490	      g_integral = 0.0f;
491	      g_last_temp_c = g_temp_c;
492	    }
493	
494	  g_kp = p;
495	  g_ki = i;
496	  g_kd = d;
497	}
498	
499	void iron_set_standby_temp(int temp_c)
500	{
501	  if (temp_c < IRON_TEMP_MIN) temp_c = IRON_TEMP_MIN;
502	  if (temp_c > IRON_TEMP_MAX) temp_c = IRON_TEMP_MAX;
503	  g_standby_c = temp_c;
504	}
505	
506	void iron_get_status(FAR struct iron_status_s *st)
507	{
508	  if (st == NULL)
509	    {
510	      return;
511	    }
512	
513	  st->temp_c       = (int)g_temp_c;
514	  st->target_c     = g_target_c;
515	  st->power_pct    = g_power;
516	  st->heating      = g_heating;
517	  st->sensor_ok    = g_sensor_ok;
518	  st->sleep_active = (g_sleep_stage != IRON_SLEEP_ACTIVE);
519	  st->target_eff_c = g_target_eff_c;
520	}
