1	/****************************************************************************
2	 * Contest 2026 team 008 - SW3538 fast-charge chip driver (NuttX)
3	 *
4	 * Four SW3538 devices share I2C address 0x3c behind a TCA9548A at 0x70.
5	 * Each transaction selects exactly one TCA downstream channel first.
6	 *
7	 * The multiplexer hangs off the software I2C bus (see cs_i2c_sw.c), so it
8	 * does not share I2C4 with the FT5x06 touchscreen.  All bus access goes
9	 * through cs_i2c_transfer(), which re-selects the channel on every call and
10	 * holds a lock across select + transfer.
11	 ****************************************************************************/
12	
13	#include <nuttx/config.h>
14	
15	#include <stdint.h>
16	#include <string.h>
17	#include <errno.h>
18	#include <syslog.h>
19	
20	#include <nuttx/i2c/i2c_master.h>
21	#include <nuttx/arch.h>
22	#include <arch/board/board.h>
23	
24	#include "cs_i2c_sw.h"
25	#include "sw3538.h"
26	
27	/****************************************************************************
28	 * Pre-processor Definitions
29	 ****************************************************************************/
30	
31	#define SW3538_ADDR              0x3c
32	#define SW3538_CHANNEL_COUNT     4
33	
34	#define SW3538_REG_PROTO         0x09
35	#define SW3538_REG_ONLINE        0x0d
36	#define SW3538_REG_ADC_SEL       0x40
37	#define SW3538_REG_ADC_LO        0x41
38	#define SW3538_REG_ADC_HI        0x42
39	#define SW3538_REG_NTC_CURRENT   0x44
40	
41	/* Reg0x40 channel codes (register list, section 2.23).
42	 *
43	 * Channels 1 and 2 are the two output paths of the chip.  Register list
44	 * 2.8 (Reg0x0A) and 2.9 (Reg0x0D) both state that for the A+C mode used
45	 * here, path 1 is the Type-C port and path 2 is the Type-A port.
46	 */
47	
48	#define ADC_CH_PATH1             1   /* Type-C port current, 2.5mA/bit@5mohm */
49	#define ADC_CH_PATH2             2   /* Type-A port current, 2.5mA/bit@5mohm */
50	#define ADC_CH_VOUT              5   /* Output voltage, 6mV/bit */
51	#define ADC_CH_VIN               6   /* Input voltage, 10mV/bit (ADC off by default) */
52	#define ADC_CH_NTC               7   /* NTC voltage, 1.2mV/bit */
53	#define ADC_CH_VOUT_CONV        11   /* Converted output voltage, 1mV/bit */
54	
55	#define NTC_UV_PER_BIT           1200u
56	#define NTC_CURRENT_LOW_UA       20u
57	#define NTC_CURRENT_HIGH_UA      40u
58	
59	/****************************************************************************
60	 * Private Data
61	 ****************************************************************************/
62	
63	/* 104AT 100K NTC nominal resistance table.  The values must be calibrated
64	 * against the actual module at room temperature before they are relied upon
65	 * for thermal decisions.  This driver reports invalid data rather than a
66	 * fabricated temperature for values outside the supported table. */
67	
68	struct ntc_point_s
69	{
70	  int16_t temp_c;
71	  uint32_t resistance_ohm;
72	};
73	
74	static const struct ntc_point_s g_ntc_104at[] =
75	{
76	  {  0, 355000 }, { 10, 202000 }, { 20, 125000 }, { 25, 100000 },
77	  { 30,  80500 }, { 40,  51000 }, { 50,  33500 }, { 60,  22400 },
78	  { 70,  15300 }, { 80,  10600 }, { 90,   7400 }, {100,   5250 },
79	  {110,   3800 }, {120,   2800 },
80	};
81	
82	/****************************************************************************
83	 * Private Functions
84	 ****************************************************************************/
85	
86	static int sw3538_read_regs(uint8_t channel, uint8_t reg, uint8_t *buf,
87	                            int len)
88	{
89	  struct i2c_msg_s msg[2];
90	  uint8_t regaddr = reg;
91	
92	  msg[0].frequency = CS_I2C_FREQ;
93	  msg[0].addr = SW3538_ADDR;
94	  msg[0].flags = 0;
95	  msg[0].buffer = &regaddr;
96	  msg[0].length = 1;
97	
98	  msg[1].frequency = CS_I2C_FREQ;
99	  msg[1].addr = SW3538_ADDR;
100	  msg[1].flags = I2C_M_READ;
101	  msg[1].buffer = buf;
102	  msg[1].length = len;
103	
104	  return cs_i2c_transfer(channel, msg, 2);
105	}
106	
107	static int sw3538_write_reg(uint8_t channel, uint8_t reg, uint8_t val)
108	{
109	  struct i2c_msg_s msg;
110	  uint8_t tx[2] = { reg, val };
111	
112	  msg.frequency = CS_I2C_FREQ;
113	  msg.addr = SW3538_ADDR;
114	  msg.flags = 0;
115	  msg.buffer = tx;
116	  msg.length = sizeof(tx);
117	  return cs_i2c_transfer(channel, &msg, 1);
118	}
119	
120	static int sw3538_adc_code(uint8_t channel, uint8_t adc, FAR uint16_t *code)
121	{
122	  uint8_t lo;
123	  uint8_t hi;
124	  int ret;
125	
126	  if (code == NULL)
127	    {
128	      return -EINVAL;
129	    }
130	
131	  ret = sw3538_write_reg(channel, SW3538_REG_ADC_SEL, adc);
132	  if (ret < 0)
133	    {
134	      return ret;
135	    }
136	
137	  up_udelay(5000);
138	
139	  ret = sw3538_read_regs(channel, SW3538_REG_ADC_LO, &lo, 1);
140	  if (ret < 0)
141	    {
142	      return ret;
143	    }
144	
145	  ret = sw3538_read_regs(channel, SW3538_REG_ADC_HI, &hi, 1);
146	  if (ret < 0)
147	    {
148	      return ret;
149	    }
150	
151	  *code = (uint16_t)(((uint16_t)(hi & 0x0f) << 8) | lo);
152	  return OK;
153	}
154	
155	static bool sw3538_ntc_to_temp(uint16_t code, uint8_t ntc_current,
156	                               FAR int16_t *temp_c)
157	{
158	  uint32_t current_ua;
159	  uint32_t resistance;
160	  unsigned int i;
161	
162	  if (code == 0 || temp_c == NULL)
163	    {
164	      return false;
165	    }
166	
167	  current_ua = (ntc_current & 0x80) ? NTC_CURRENT_HIGH_UA :
168	                                      NTC_CURRENT_LOW_UA;
169	  resistance = ((uint32_t)code * NTC_UV_PER_BIT) / current_ua;
170	
171	  if (resistance > g_ntc_104at[0].resistance_ohm ||
172	      resistance < g_ntc_104at[(sizeof(g_ntc_104at) /
173	                                 sizeof(g_ntc_104at[0])) - 1].resistance_ohm)
174	    {
175	      return false;
176	    }
177	
178	  for (i = 0; i < (sizeof(g_ntc_104at) / sizeof(g_ntc_104at[0])) - 1; i++)
179	    {
180	      const struct ntc_point_s *high = &g_ntc_104at[i];
181	      const struct ntc_point_s *low = &g_ntc_104at[i + 1];
182	
183	      if (resistance <= high->resistance_ohm &&
184	          resistance >= low->resistance_ohm)
185	        {
186	          uint32_t span = high->resistance_ohm - low->resistance_ohm;
187	          uint32_t offset = high->resistance_ohm - resistance;
188	
189	          *temp_c = (int16_t)(high->temp_c +
190	                    ((int32_t)offset * (low->temp_c - high->temp_c) / span));
191	          return true;
192	        }
193	    }
194	
195	  return false;
196	}
197	
198	/****************************************************************************
199	 * Public Functions
200	 ****************************************************************************/
201	
202	int sw3538_init(void)
203	{
204	  int ret;
205	
206	  ret = cs_i2c_bus_init();
207	  if (ret < 0)
208	    {
209	      syslog(LOG_ERR, "SW3538: software I2C bus init failed\n");
210	      return ret;
211	    }
212	
213	  ret = cs_i2c_mux_probe();
214	  if (ret < 0)
215	    {
216	      syslog(LOG_ERR, "SW3538: no TCA9548A ACK at 0x%02x\n", CS_TCA9548A_ADDR);
217	      return ret;
218	    }
219	
220	  syslog(LOG_INFO, "SW3538: TCA9548A ready at 0x%02x on software I2C\n",
221	         CS_TCA9548A_ADDR);
222	  return OK;
223	}
224	
225	int sw3538_read_status_channel(uint8_t channel,
226	                                FAR struct sw3538_status_s *st)
227	{
228	  uint16_t code;
229	  uint8_t proto;
230	  uint8_t online;
231	  uint8_t ntc_current;
232	  int ret;
233	
234	  if (st == NULL || channel >= SW3538_CHANNEL_COUNT)
235	    {
236	      return -EINVAL;
237	    }
238	
239	  memset(st, 0, sizeof(*st));
240	
241	  ret = sw3538_read_regs(channel, SW3538_REG_PROTO, &proto, 1);
242	  if (ret < 0)
243	    {
244	      return ret;
245	    }
246	
247	  ret = sw3538_read_regs(channel, SW3538_REG_ONLINE, &online, 1);
248	  if (ret < 0)
249	    {
250	      return ret;
251	    }
252	
253	  ret = sw3538_adc_code(channel, ADC_CH_VOUT, &code);
254	  if (ret < 0)
255	    {
256	      return ret;
257	    }
258	  st->vout_mv = (uint16_t)(code * 6u);
259	
260	  ret = sw3538_adc_code(channel, ADC_CH_PATH1, &code);
261	  if (ret < 0)
262	    {
263	      return ret;
264	    }
265	  st->ic_ma = (uint16_t)(code * 25u / 10u);
266	
267	  ret = sw3538_adc_code(channel, ADC_CH_PATH2, &code);
268	  if (ret < 0)
269	    {
270	      return ret;
271	    }
272	  st->ia_ma = (uint16_t)(code * 25u / 10u);
273	
274	  ret = sw3538_read_regs(channel, SW3538_REG_NTC_CURRENT, &ntc_current, 1);
275	  if (ret < 0)
276	    {
277	      return ret;
278	    }
279	
280	  ret = sw3538_adc_code(channel, ADC_CH_NTC, &code);
281	  if (ret < 0)
282	    {
283	      return ret;
284	    }
285	
286	  st->temp_valid = sw3538_ntc_to_temp(code, ntc_current, &st->temp_c);
287	  st->proto = proto & 0x0f;
288	  st->online = online & 0x03;
289	  return OK;
290	}
291	
292	int sw3538_read_status(FAR struct sw3538_status_s *st)
293	{
294	  return sw3538_read_status_channel(0, st);
295	}
296	
297	const char *sw3538_proto_name(uint8_t proto)
298	{
299	  switch (proto)
300	    {
301	      case 0:  return "IDLE";
302	      case 1:  return "QC2.0";
303	      case 2:  return "QC3.0";
304	      case 3:  return "QC3+";
305	      case 4:  return "FCP";
306	      case 5:  return "SCP";
307	      case 6:  return "PD";
308	      case 7:  return "PD-PPS";
309	      case 8:  return "PE1.1";
310	      case 9:  return "PE2.0";
311	      case 10: return "VOOC1";
312	      case 11: return "VOOC4";
313	      case 13: return "SFCP";
314	      case 14: return "AFC";
315	      case 15: return "TFCP";
316	      default: return "?";
317	    }
318	}
