1	/****************************************************************************
2	 * Contest 2026 team 008 - software (bit-bang) I2C transport
3	 *
4	 * Wraps the generic NuttX i2c_bitbang engine (CONFIG_I2C_BITBANG) with
5	 * STM32H7 GPIO operations and adds atomic TCA9548A channel selection.
6	 ****************************************************************************/
7	
8	#include <nuttx/config.h>
9	
10	#include <stdint.h>
11	#include <stdbool.h>
12	#include <errno.h>
13	#include <syslog.h>
14	
15	#include <nuttx/arch.h>
16	#include <nuttx/mutex.h>
17	#include <nuttx/i2c/i2c_master.h>
18	#include <nuttx/i2c/i2c_bitbang.h>
19	
20	#include "cs_i2c_sw.h"
21	
22	/* Chip headers are not on the app include path; the generic GPIO API is
23	 * declared here and pinsets are built from the documented bit layout:
24	 *   MODE bits18-19 (OUTPUT=1<<18), SPEED bits10-11 (50MHz=2<<10),
25	 *   OPEN-DRAIN bit9, OUTPUT_SET bit8, PUPD bits16-17 (PULLUP=1<<16),
26	 *   PORT bits4-7 (A=0,K=10), PIN bits0-3
27	 */
28	
29	extern int  stm32_configgpio(uint32_t cfgset);
30	extern void stm32_gpiowrite(uint32_t pinset, bool value);
31	extern bool stm32_gpioread(uint32_t pinset);
32	
33	/****************************************************************************
34	 * Pre-processor Definitions
35	 ****************************************************************************/
36	
37	#define GPIO_OUTPUT_VAL     (1u << 18)
38	#define GPIO_SPEED_50MHZ    (2u << 10)
39	#define GPIO_OUTPUT_SETBIT  (1u << 8)
40	#define GPIO_OPENDRAIN_VAL  (1u << 9)
41	#define GPIO_PULLUP         (1u << 16)
42	
43	#define CS_I2C_SCL_PIN      (GPIO_OUTPUT_VAL | GPIO_SPEED_50MHZ | \
44	                             GPIO_OPENDRAIN_VAL | GPIO_OUTPUT_SETBIT | \
45	                             GPIO_PULLUP | (10u << 4) | 1u)  /* D4 = PK1 */
46	#define CS_I2C_SDA_PIN      (GPIO_OUTPUT_VAL | GPIO_SPEED_50MHZ | \
47	                             GPIO_OPENDRAIN_VAL | GPIO_OUTPUT_SETBIT | \
48	                             GPIO_PULLUP | (0u << 4) | 8u)   /* D5 = PA8 */
49	
50	/****************************************************************************
51	 * Private Types
52	 ****************************************************************************/
53	
54	struct cs_i2c_priv_s
55	{
56	  uint32_t scl;    /* SCL pinset */
57	  uint32_t sda;    /* SDA pinset */
58	};
59	
60	/****************************************************************************
61	 * Private Data
62	 ****************************************************************************/
63	
64	static struct cs_i2c_priv_s g_cs_i2c_priv =
65	{
66	  CS_I2C_SCL_PIN,
67	  CS_I2C_SDA_PIN
68	};
69	
70	static struct i2c_bitbang_lower_dev_s g_cs_i2c_lower;
71	static FAR struct i2c_master_s *g_cs_i2c_bus;
72	static mutex_t g_cs_i2c_lock = NXMUTEX_INITIALIZER;
73	
74	/****************************************************************************
75	 * Private Functions
76	 ****************************************************************************/
77	
78	/* The bit-bang engine calls these from inside a spinlock, so they must stay
79	 * trivial: no delays, no logging, no allocation. */
80	
81	static void cs_i2c_initialize(FAR struct i2c_bitbang_lower_dev_s *lower)
82	{
83	  FAR struct cs_i2c_priv_s *priv = lower->priv;
84	
85	  stm32_configgpio(priv->scl);
86	  stm32_configgpio(priv->sda);
87	
88	  /* Release both lines so the bus idles high.  Whether the lines actually
89	   * came up is checked once by cs_i2c_bus_init(). */
90	
91	  stm32_gpiowrite(priv->scl, true);
92	  stm32_gpiowrite(priv->sda, true);
93	}
94	
95	static void cs_i2c_set_scl(FAR struct i2c_bitbang_lower_dev_s *lower,
96	                           bool high)
97	{
98	  FAR struct cs_i2c_priv_s *priv = lower->priv;
99	
100	  stm32_gpiowrite(priv->scl, high);
101	}
102	
103	static void cs_i2c_set_sda(FAR struct i2c_bitbang_lower_dev_s *lower,
104	                           bool high)
105	{
106	  FAR struct cs_i2c_priv_s *priv = lower->priv;
107	
108	  stm32_gpiowrite(priv->sda, high);
109	}
110	
111	static bool cs_i2c_get_scl(FAR struct i2c_bitbang_lower_dev_s *lower)
112	{
113	  FAR struct cs_i2c_priv_s *priv = lower->priv;
114	
115	  return stm32_gpioread(priv->scl);
116	}
117	
118	static bool cs_i2c_get_sda(FAR struct i2c_bitbang_lower_dev_s *lower)
119	{
120	  FAR struct cs_i2c_priv_s *priv = lower->priv;
121	
122	  return stm32_gpioread(priv->sda);
123	}
124	
125	/****************************************************************************
126	 * Public Functions
127	 ****************************************************************************/
128	
129	int cs_i2c_bus_init(void)
130	{
131	  static const struct i2c_bitbang_lower_ops_s ops =
132	  {
133	    cs_i2c_initialize,
134	    cs_i2c_set_scl,
135	    cs_i2c_set_sda,
136	    cs_i2c_get_scl,
137	    cs_i2c_get_sda
138	  };
139	
140	  /* Idempotent: a second i2c_bitbang_initialize() would allocate a second
141	   * master with its own spinlock driving the same pins. */
142	
143	  if (g_cs_i2c_bus != NULL)
144	    {
145	      return OK;
146	    }
147	
148	  g_cs_i2c_lower.ops  = &ops;
149	  g_cs_i2c_lower.priv = &g_cs_i2c_priv;
150	
151	  g_cs_i2c_bus = i2c_bitbang_initialize(&g_cs_i2c_lower);
152	  if (g_cs_i2c_bus == NULL)
153	    {
154	      syslog(LOG_ERR, "CS-I2C: bit-bang master init failed\n");
155	      return -ENODEV;
156	    }
157	
158	  /* Lines should idle high; a low reading means no pull-up or bad wiring. */
159	
160	  if (!stm32_gpioread(g_cs_i2c_priv.scl) ||
161	      !stm32_gpioread(g_cs_i2c_priv.sda))
162	    {
163	      syslog(LOG_WARNING, "CS-I2C: SCL(D4/PK1)=%d SDA(D5/PA8)=%d stuck low - "
164	             "check pull-ups and wiring\n",
165	             stm32_gpioread(g_cs_i2c_priv.scl),
166	             stm32_gpioread(g_cs_i2c_priv.sda));
167	    }
168	
169	  syslog(LOG_INFO, "CS-I2C: software bus ready (SCL=D4/PK1, SDA=D5/PA8, "
170	         "%ukHz)\n", CS_I2C_FREQ / 1000u);
171	  return OK;
172	}
173	
174	bool cs_i2c_bus_ready(void)
175	{
176	  return g_cs_i2c_bus != NULL;
177	}
178	
179	int cs_i2c_mux_probe(void)
180	{
181	  struct i2c_msg_s msg;
182	  uint8_t value = 0;
183	
184	  if (g_cs_i2c_bus == NULL)
185	    {
186	      return -ENODEV;
187	    }
188	
189	  /* A single register device: write 0 to deselect every downstream channel. */
190	
191	  msg.frequency = CS_I2C_FREQ;
192	  msg.addr      = CS_TCA9548A_ADDR;
193	  msg.flags     = 0;
194	  msg.buffer    = &value;
195	  msg.length    = 1;
196	
197	  return I2C_TRANSFER(g_cs_i2c_bus, &msg, 1);
198	}
199	
200	int cs_i2c_transfer(uint8_t channel, FAR struct i2c_msg_s *msgs, int count)
201	{
202	  struct i2c_msg_s sel;
203	  uint8_t value;
204	  int i;
205	  int ret;
206	
207	  if (g_cs_i2c_bus == NULL || msgs == NULL || count <= 0 || channel > 7)
208	    {
209	      return -EINVAL;
210	    }
211	
212	  /* The bit-bang engine divides by msg->frequency; never let it be zero. */
213	
214	  for (i = 0; i < count; i++)
215	    {
216	      if (msgs[i].frequency == 0)
217	        {
218	          msgs[i].frequency = CS_I2C_FREQ;
219	        }
220	    }
221	
222	  /* Selecting the channel and talking to the device must be atomic. */
223	
224	  nxmutex_lock(&g_cs_i2c_lock);
225	
226	  value         = (uint8_t)(1u << channel);
227	  sel.frequency = CS_I2C_FREQ;
228	  sel.addr      = CS_TCA9548A_ADDR;
229	  sel.flags     = 0;
230	  sel.buffer    = &value;
231	  sel.length    = 1;
232	
233	  ret = I2C_TRANSFER(g_cs_i2c_bus, &sel, 1);
234	  if (ret >= 0)
235	    {
236	      ret = I2C_TRANSFER(g_cs_i2c_bus, msgs, count);
237	    }
238	
239	  nxmutex_unlock(&g_cs_i2c_lock);
240	  return ret;
241	}
