1008	/****************************************************************************
1009	 * Name: cs_ui_set_ch1_real
1010	 *
1011	 * Feed real SW3538 readings into channel 1 display.
1012	 * Volt in volts, amp in amps. If online is false, port shows idle.
1013	 ****************************************************************************/
1014	
1015	void cs_ui_set_channel_ports(int channel, float c_volt, float c_amp,
1016	                             float a_volt, float a_amp, const char *proto,
1017	                             int temp_c, bool temp_valid)
1018	{
1019	  chan_t *chan;
1020	
1021	  if (channel < 0 || channel >= 4)
1022	    {
1023	      return;
1024	    }
1025	
1026	  chan = &g_chan[channel];
1027	  snprintf(g_chan_c_proto[channel], sizeof(g_chan_c_proto[channel]), "%s",
1028	           proto != NULL ? proto : "IDLE");
1029	  snprintf(g_chan_a_proto[channel], sizeof(g_chan_a_proto[channel]), "%s",
1030	           proto != NULL ? proto : "IDLE");
1031	
1032	  if (c_amp > 0.01f)
1033	    {
1034	      chan->c_proto = g_chan_c_proto[channel];
1035	      chan->c_volt = c_volt;
1036	      chan->c_amp = c_amp;
1037	      chan->c_watt = c_volt * c_amp;
1038	    }
1039	  else
1040	    {
1041	      chan->c_proto = "IDLE";
1042	      chan->c_volt = 0.0f;
1043	      chan->c_amp = 0.0f;
1044	      chan->c_watt = 0.0f;
1045	    }
1046	
1047	  if (a_amp > 0.01f)
1048	    {
