169	      stm32_gpiowrite(IRON_GPIO_SCK, false);
170	      iron_spi_delay();
171	
172	      /* Sample SO on rising edge per MAX6675: data changes on falling
173	       * edge, so read while clock is low (stable). */
174	      value = (value << 1);
175	      if (stm32_gpioread(IRON_GPIO_SO))
176	        {
177	          value |= 1;
178	        }
179	
180	      /* SCK high */
181	      stm32_gpiowrite(IRON_GPIO_SCK, true);
182	      iron_spi_delay();
183	    }
184	
185	  /* CS high to end */
186	  stm32_gpiowrite(IRON_GPIO_CS, true);
187	  iron_spi_delay();
188	
189	  return value;
190	}
