192	/****************************************************************************
193	 * Name: max6675_temp
194	 *
195	 * Decode 16-bit read into Celsius. Returns -1000 if thermocouple open.
196	 ****************************************************************************/
197	
198	static bool max6675_temp(uint16_t raw, FAR float *temp_c)
199	{
200	  uint16_t code;
201	
202	  if (temp_c == NULL || (raw & 0x8000) != 0 || (raw & 0x0002) != 0 ||
203	      (raw & 0x0004) != 0)
204	    {
205	      return false;
206	    }
207	
208	  code = (raw >> 3) & 0x0fff;
209	  *temp_c = (float)code * 0.25f;
210	  return *temp_c >= 0.0f && *temp_c <= 1023.75f;
211	}
212	
213	/****************************************************************************
214	 * Name: iron_pid_update
215	 *
216	 * Compute heater power % from PID on temperature error.
217	 ****************************************************************************/
218	
219	static void iron_pid_update(float dt)
220	{
221	  float error;
222	  float p_term;
223	  float i_term;
224	  float d_term;
225	  float d_slope;
226	  float candidate;
227	
228	  if (!g_heating || !g_sensor_ok || !g_have_sample)
229	    {
230	      g_power = 0.0f;
231	      g_integral = 0.0f;
232	      return;
233	    }
234	
235	  error = (float)g_target_eff_c - g_temp_c;
236	  p_term = g_kp * error;
237	  d_slope = (g_temp_c - g_last_temp_c) / dt;
238	  if (d_slope > IRON_D_MAX_SLOPE) d_slope = IRON_D_MAX_SLOPE;
239	  if (d_slope < -IRON_D_MAX_SLOPE) d_slope = -IRON_D_MAX_SLOPE;
240	  d_term = -g_kd * d_slope;
241	
242	  /* Conditional integration: do not integrate farther into saturation. */
243	  candidate = p_term + g_ki * g_integral + d_term;
244	  if (!((candidate >= IRON_PWR_MAX && error > 0.0f) ||
245	        (candidate <= 0.0f && error < 0.0f)))
246	    {
247	      g_integral += error * dt;
248	      if (g_integral > 1000.0f) g_integral = 1000.0f;
249	      if (g_integral < -1000.0f) g_integral = -1000.0f;
250	    }
251	
252	  i_term = g_ki * g_integral;
253	  g_power = p_term + i_term + d_term;
254	  if (g_power < 0.0f) g_power = 0.0f;
255	  if (g_power > IRON_PWR_MAX) g_power = IRON_PWR_MAX;
256	}
257	
258	/****************************************************************************
259	 * Name: iron_pwm_apply
260	 *
261	 * Software PWM: turn heater GPIO on/off based on power %.
262	 * Called once per tick (100ms). We split the 100ms into N slices and
263	 * keep the heater on for the first (power%) slices.
264	 ****************************************************************************/
265	
266	static void iron_pwm_apply(void)
267	{
268	  /* Round rather than truncate: a floor here would bias every duty cycle
269	   * downwards by up to one full slice. */
270	
271	  int on_slices = (int)(g_power / 100.0f * IRON_PWM_TICKS + 0.5f);
272	
273	  if (!g_heating || on_slices <= 0)
274	    {
275	      g_pwm_slice = 0;
276	      stm32_gpiowrite(IRON_GPIO_HEAT, false);
277	      return;
278	    }
279	
280	  if (on_slices >= IRON_PWM_TICKS)
281	    {
282	      /* Constant on: restart the phase so a later drop back to a partial
283	       * duty cycle starts from a clean slice rather than a stale one. */
284	
285	      g_pwm_slice = 0;
286	      stm32_gpiowrite(IRON_GPIO_HEAT, true);
287	      return;
288	    }
289	
290	  stm32_gpiowrite(IRON_GPIO_HEAT, g_pwm_slice < on_slices);
291	  g_pwm_slice++;
292	  if (g_pwm_slice >= IRON_PWM_TICKS)
293	    {
294	      g_pwm_slice = 0;
295	    }
296	}
297	
298	/****************************************************************************
299	 * Name: iron_sleep_tick
300	 *
301	 * Debounce the JBC245 SLEEP pin.  The handle pulls the line low while the
302	 * iron rests in its stand, so an active-low reading means "parked".
303	 *
304	 * Parked irons do not heat at all: the heater is held off for as long as
305	 * the pin reads low, and the PID state is cleared so that picking the iron
306	 * back up starts from a clean controller rather than from whatever the
307	 * integrator had accumulated before it was put down.
308	 ****************************************************************************/
309	
310	static void iron_sleep_tick(void)
311	{
312	  bool raw;
313	
314	  raw = !stm32_gpioread(IRON_GPIO_SLEEP);   /* active low: in stand */
315	
316	  /* Bounce filter: require N consecutive identical samples. */
317	  if (raw != g_sleep_pin_deb)
318	    {
319	      g_sleep_deb_cnt++;
320	      if (g_sleep_deb_cnt >= IRON_SLEEP_DEBOUNCE_TICKS)
321	        {
322	          g_sleep_pin_deb = raw;
323	          g_sleep_deb_cnt = 0;
324	        }
325	    }
326	  else
327	    {
328	      g_sleep_deb_cnt = 0;
329	    }
330	
331	  if (g_sleep_pin_deb == g_parked)
332	    {
333	      return;   /* no transition */
334	    }
335	
336	  if (g_sleep_pin_deb)
337	    {
338	      /* Just parked: stop heating and drop the PID history. */
339	      g_parked = true;
340	      g_power       = 0.0f;
341	      g_integral    = 0.0f;
342	      g_pwm_slice   = 0;
343	      g_last_temp_c = g_temp_c;
344	      g_target_eff_c = g_target_c;
345	      stm32_gpiowrite(IRON_GPIO_HEAT, false);
346	      syslog(LOG_INFO, "IRON: parked, heater off\n");
347	    }
348	  else
349	    {
350	      /* Picked back up: resume the user target with a clean controller. */
351	      g_parked = false;
352	      g_integral    = 0.0f;
353	      g_last_temp_c = g_temp_c;
354	      g_target_eff_c = g_target_c;
355	      syslog(LOG_INFO, "IRON: picked up, resuming %dC\n", g_target_c);
356	    }
357	}
358	
359	/* Returns true while the iron is parked in its stand (SLEEP line low). */
360	
361	static bool iron_is_parked(void)
362	{
363	  return g_parked;
364	}
365	
366	
367	int iron_init(void)
368	{
369	  /* Configure GPIO pins */
370	  stm32_configgpio(IRON_GPIO_SCK);
371	  stm32_configgpio(IRON_GPIO_CS);
372	  stm32_configgpio(IRON_GPIO_SO);
373	  stm32_configgpio(IRON_GPIO_HEAT);
374	  stm32_configgpio(IRON_GPIO_SLEEP);
375	
376	  /* Idle states: CS high, clock low, heater off */
377	  stm32_gpiowrite(IRON_GPIO_CS, true);
378	  stm32_gpiowrite(IRON_GPIO_SCK, false);
379	  stm32_gpiowrite(IRON_GPIO_HEAT, false);
380	
381	  /* Probe MAX6675 */
382	  {
383	    uint16_t raw = max6675_read();
384	    float t;
385	
386	    if (!max6675_temp(raw, &t))
387	      {
388	        syslog(LOG_WARNING, "IRON: invalid MAX6675 frame (raw=0x%04x)\n", raw);
389	        g_sensor_ok = false;
390	      }
391	    else
392	      {
393	        g_temp_c = t;
394	        g_last_temp_c = t;
395	        g_have_sample = true;
396	        g_sample_age = 0.0f;
397	        g_sensor_ok = true;
398	        syslog(LOG_INFO, "IRON: MAX6675 ok, T=%.1fC (raw=0x%04x)\n", t, raw);
399	      }
400	  }
401	
402	  return 0;
403	}
404	
405	void iron_tick(void)
406	{
407	  static int read_div = 0;
408	  uint16_t raw;
409	  float t;
410	  bool fresh_sample = false;
411	
412	  g_sample_age += IRON_PID_DT;
413	
414	  /* JBC245 sleep detection runs every tick, before sampling. */
415	  iron_sleep_tick();
416	
417	  /* CS high starts a conversion.  Read only after three 100ms ticks so the
418	   * MAX6675 has exceeded its 220ms maximum conversion time. */
419	  if (++read_div >= 3)
420	    {
421	      read_div = 0;
422	      raw = max6675_read();
423	
424	      if (max6675_temp(raw, &t))
425	        {
426	          if (t >= IRON_TEMP_CUTOFF)
427	            {
428	              syslog(LOG_WARNING, "IRON: over-temperature %.1fC\n", t);
429	              g_sensor_ok = false;
430	            }
431	          else
432	            {
433	              g_last_temp_c = g_temp_c;
434	              g_temp_c = t;
435	              g_sample_age = 0.0f;
436	              g_have_sample = true;
437	              g_sensor_ok = true;
438	              fresh_sample = true;
439	            }
440	        }
441	      else
442	        {
443	          syslog(LOG_WARNING, "IRON: invalid MAX6675 frame (raw=0x%04x)\n", raw);
444	          g_sensor_ok = false;
445	        }
446	    }
447	
448	  if (!g_sensor_ok || g_sample_age > IRON_SAMPLE_MAX_AGE)
449	    {
450	      /* A stale or invalid sensor reading must always shut the heater off. */
451	      g_sensor_ok = false;
452	      g_power = 0.0f;
453	      g_integral = 0.0f;
454	      g_pwm_slice = 0;
455	      stm32_gpiowrite(IRON_GPIO_HEAT, false);
456	      return;
457	    }
458	
459	  /* Parked in the stand: no heating at all, regardless of the target. */
460	
461	  if (iron_is_parked())
462	    {
463	      g_power = 0.0f;
464	      g_integral = 0.0f;
465	      g_pwm_slice = 0;
466	      g_last_temp_c = g_temp_c;
467	      stm32_gpiowrite(IRON_GPIO_HEAT, false);
468	      return;
469	    }
470	
471	  if (fresh_sample)
472	    {
473	      iron_pid_update(IRON_PID_DT * 3.0f);
474	    }
475	
476	  iron_pwm_apply();
477	}
478	
479	void iron_set_target(int temp_c)
480	{
481	  if (temp_c < IRON_TEMP_MIN) temp_c = IRON_TEMP_MIN;
482	  if (temp_c > IRON_TEMP_MAX) temp_c = IRON_TEMP_MAX;
483	  if (temp_c != g_target_c)
484	    {
485	      g_integral = 0.0f;
486	      g_last_temp_c = g_temp_c;
487	    }
488	
489	  g_target_c = temp_c;
490	
491	  /* While parked the target is remembered but not acted on; the effective
492	   * target is restored when the iron is picked up again. */
493	
494	  if (!iron_is_parked())
495	    {
496	      g_target_eff_c = temp_c;
497	    }
498	}
499	
500	void iron_set_heater(bool on)
501	{
502	  g_heating = on;
503	  if (!on)
504	    {
505	      g_integral = 0.0f;
506	      g_last_temp_c = g_temp_c;
507	      g_power = 0.0f;
508	      g_pwm_slice = 0;
509	      g_sleep_pin_deb = !stm32_gpioread(IRON_GPIO_SLEEP);
510	      g_sleep_deb_cnt = 0;
511	      g_parked = g_sleep_pin_deb;
512	      g_target_eff_c = g_target_c;
513	      stm32_gpiowrite(IRON_GPIO_HEAT, false);
514	    }
515	}
516	
517	void iron_set_pid(float p, float i, float d)
518	{
519	  if (!isfinite(p) || !isfinite(i) || !isfinite(d) || p < 0.0f ||
520	      i < 0.0f || d < 0.0f || p > IRON_PID_KP_MAX ||
521	      i > IRON_PID_KI_MAX || d > IRON_PID_KD_MAX)
522	    {
523	      syslog(LOG_WARNING, "IRON: rejected invalid PID P=%.2f I=%.2f D=%.2f\n", p, i, d);
524	      return;
525	    }
526	
527	  if (p != g_kp || i != g_ki || d != g_kd)
528	    {
529	      g_integral = 0.0f;
530	      g_last_temp_c = g_temp_c;
531	    }
532	
533	  g_kp = p;
534	  g_ki = i;
535	  g_kd = d;
536	}
537	
538	void iron_get_status(FAR struct iron_status_s *st)
539	{
540	  if (st == NULL)
541	    {
542	      return;
543	    }
544	
545	  st->temp_c       = (int)g_temp_c;
546	  st->target_c     = g_target_c;
547	  st->power_pct    = g_power;
548	  st->heating      = g_heating;
549	  st->sensor_ok    = g_sensor_ok;
550	  st->sleep_active = g_parked;
551	  st->target_eff_c = g_target_eff_c;
552	}
