1148	      lv_obj_set_style_bg_color(g_chan_c_proto_lbl[i],
1149	                                proto_color(strcmp(g_chan[i].c_proto,
1150	                                                   "IDLE") != 0 ?
1151	                                            g_chan[i].c_proto :
1152	                                            g_chan[i].a_proto), 0);
1153	
1154	      if (strcmp(g_chan[i].a_proto, "IDLE") != 0)
