1163	          lv_label_set_text(g_chan_a_lbl[i], "--.-V  --.--A  --.-W");
1164	          lv_obj_set_style_text_color(g_chan_a_lbl[i], COLOR_IRON_DIM, 0);
1165	        }
1166	
1167	      if (g_chan[i].temp_valid)
1168	        {
1169	          lv_label_set_text_fmt(g_chan_temp_lbl[i], "TEMP %d°C",
1170	                                g_chan[i].die_temp);
