1176	          lv_obj_set_style_text_color(g_chan_temp_lbl[i], COLOR_IRON_DIM, 0);
1177	        }
1178	    }
1179	
1180	  /* Iron display: values updated from real hardware via
1181	   * cs_ui_set_iron_real(). Here we only render + advance charts.
1182	   */
1183	  lv_label_set_text_fmt(g_iron_temp_lbl, "%d", g_iron_temp);
1184	  lv_label_set_text_fmt(g_iron_pwr_lbl, "%.0f%%", (float)g_iron_power);
1185	
1186	  /* Status: the parked iron does not heat at all, so it reports SLEEP
1187	   * (orange) even when the heat switch is on.  Otherwise: OFF (gray),
1188	   * READY (green) when within ~5C of target, HEATING (red) otherwise. */
1189	  if (g_iron_sleep_active)
1190	    {
