1208	    }
1209	
1210	  ui_iron_update_heat_button();
1211	
1212	  /* Target readout.  ui_iron_set_target() also writes it on user input;
1213	   * refreshing it here keeps it correct across park/pickup transitions. */
1214	
1215	  lv_label_set_text_fmt(g_iron_slider_lbl, "TARGET %d°C", g_iron_target_eff);
