837	
838	  if (step == NULL || step->label == NULL) return;
839	
840	  switch (step->row)
841	    {
842	      case 0: /* P: 0..100 step 5 */
843	        max = 100; delta = 5;
844	        break;
845	      case 1: /* I: 0.0..5.0 step 0.1 */
846	        max = 50; delta = 1;
847	        break;
848	      default: /* D: 0..100 step 5 */
849	        max = 100; delta = 5;
850	        break;
851	    }
852	
853	  g_pid_value[step->row].value += step->increment ? delta : -delta;
854	  if (g_pid_value[step->row].value < 0)
855	    g_pid_value[step->row].value = 0;
856	  if (g_pid_value[step->row].value > max) g_pid_value[step->row].value = max;
